pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let c = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    if post_residual > 0 && post_residual < 16 { score += 60.0 ; }
    else if post_residual < 30 { score += (30 - post_residual) as f64 * 1.5 ; }
    if post_residual == 0 { score -= 150.0 ; }
    let tightness = 1.0 - pr / c ;
    score -= 25.0 * tightness * tightness ;
    let quarter = bin_capacity / 4 ;
    let eighth = bin_capacity / 8 ;
    if post_residual > eighth && post_residual < quarter { score += 15.0 ; }
    if next_item_size > 0 {
        if next_item_size == post_residual { score -= 120.0 ; }
        else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64 ;
            score -= 20.0 * (1.0 - slack / c) ;
            if slack < 8.0 { score -= 10.0 ; }
        } else { score += 8.0 ; }
    }
    let fill_ratio = item_size as f64 / bin_residual . max (1) as f64 ;
    score -= 10.0 * fill_ratio ;
    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let pressure = (open_bins_count as f64) . ln () . max (0.0) ;
    score += 3.0 * pressure * (1.0 - fill_ratio) ;
    score += 0.3 * (mean_residual - bin_residual as f64) . max (- 50.0) ;
    // lookahead: penalize bins whose residual would become unusable dead space
    if post_residual > 0 && next_item_size > post_residual {
        score += 0.08 * (post_residual as f64) ;
    }
    if bin_residual == bin_capacity {
        score = 25.0 - 0.15 * item_size as f64 ;
        if fitting_bins_count == 1 && post_residual > 40 { score -= 15.0 ; }
        score -= 10.0 * (1.0 - progress) ;
        if mean_residual > 30.0 { score += 12.0 ; }
        if next_item_size > 0 && next_item_size > item_size { score -= 6.0 ; }
        // prefer new bin when open-bin fits are all poor (large post-residual)
        if fitting_bins_count >= 1 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 4.0 ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: small post_residual is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that cannot fit the average next item.
    if next_item_size > 0 {
        let gap = post_residual as f64;
        if (next_item_size as f64) > gap {
            score += 12.0 * (next_item_size as f64 - gap);
        } else {
            // Reward leaving room for the lookahead item.
            score -= 6.0 * (gap - next_item_size as f64).min(20.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0 + 0.25 * (bin_residual as f64 - item_size as f64);
    } else if fitting_bins_count > 2 {
        // Many options: mildly prefer bins with larger residual (best-fit still dominates).
        score += 0.05 * (fitting_bins_count as f64);
    }

    // Penalize bins far from the mean residual (fragmentation pressure).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // New-bin candidate handling: empty bin gets a mild penalty so it's only chosen
    // when all open bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 + 8.0 * progress;
        // If no open bin fits (fitting_bins_count includes only this new bin), accept it.
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
    }

    // Late in the stream, consolidate: favor reusing existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 0.03 * (open_bins_count as f64);

    score
}

