pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let c = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 260.0;
    }

    // Fragmentation avoidance: penalize tiny unusable residuals
    if post_residual > 0 && post_residual < 16 {
        score += 65.0;
    } else if post_residual < 30 {
        score += (30 - post_residual) as f64 * 1.4;
    }

    // Tightness reward: quadratic preference for low post residual
    let tightness = 1.0 - pr / c;
    score -= 28.0 * tightness * tightness;

    // Dead-space band penalty: residuals in the awkward 1/8..1/4 zone waste space
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    if post_residual > eighth && post_residual < quarter {
        score += 18.0;
    }

    // 2-step lookahead: exact match of next item into post residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 320.0;
        } else if post_residual > next_item_size {
            let slack_after_two = (post_residual - next_item_size) as f64;
            // reward small slack, penalize large slack
            score -= 110.0 * (1.0 - slack_after_two / c);
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.55;
        }
    }

    // Compare post_residual against mean residual: avoid creating outliers
    let mean_post = mean_residual - item_size as f64;
    let dev = post_residual as f64 - mean_post;
    if dev < 0.0 {
        score += dev * 0.3;
    } else {
        score += dev * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 140.0;
    }

    // New-bin candidate handling: open only when open bins are too tight
    if bin_residual == bin_capacity {
        let tight_open = mean_residual < item_size as f64 + 5.0
            || (fitting_bins_count <= 1 && next_item_size as f64 > mean_residual);
        if tight_open {
            score -= 85.0;
        } else {
            score += 230.0 + mean_residual * 0.5;
        }
    }

    // Consolidation pressure as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 28.0 * (pr / c);

    score
}

