pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        let post_f = post_residual as f64;
        if post_f >= next_f {
            let match_gap = post_f - next_f;
            // Strong reward if the next item fits perfectly here
            if match_gap == 0.0 {
                score -= 500.0;
            } else {
                // decayed reward for near matches
                score -= 200.0 / (1.0 + match_gap / 20.0);
            }
        } else {
            // next item cannot use this bin's leftover; penalize dead space
            score += (next_f - post_f).min(60.0) * 0.5;
        }
    }

    // Prefer tighter fits relative to the mean residual of open bins
    let post_f = post_residual as f64;
    if post_f > mean_residual {
        score += (post_f - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - post_f) * 0.1;
    }

    // Last-chance bin: avoid opening a new bin if this fits reasonably
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would waste a lot
    if bin_residual == bin_capacity {
        // neutral baseline slightly above a good fit
        score += 30.0;
        // early stream: be more willing to open bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 20.0;
        // if many open bins are fragmented, new bin is attractive
        if mean_residual < 30.0 {
            score -= 40.0;
        }
    }

    // Penalize creating small unusable slivers (< 10, the min item size historically)
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Any post_residual below the minimum item size (1) is impossible here,
    // but gaps too small to ever be reused by typical items are "dead space".
    // Penalize small-but-nonzero gaps superlinearly: they are the true waste.
    if post_residual > 0 {
        // Small gaps (hard to fill) get a heavy quadratic penalty.
        if post_residual <= 20 {
            score += (21.0 - post_residual as f64) * (21.0 - post_residual as f64) * 1.5;
        } else if post_residual <= 40 {
            // Moderate gaps: mild penalty to prefer tighter fits elsewhere.
            score += (41.0 - post_residual as f64) * 0.5;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // --- Last-chance bonus ---
    // If this is the ONLY bin that can fit the item, using it avoids opening
    // a new bin; reward strongly, scaled by how tight the fit is.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + (bin_residual - item_size) as f64 * 0.3;
    }

    // --- Open-bin pressure ---
    // Favor reusing existing bins when many bins are already open,
    // to keep the active set compact.
    score += open_bins_count as f64 * 0.8;

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin: baseline is post_residual = capacity - item_size,
        // which already looks attractive for small items. Add a fixed opening
        // penalty so we only open when no decent fit exists among open bins.
        score += 55.0;
        // If no open bin fits at all, opening is unavoidable: cancel the penalty.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // --- Lookahead coupling ---
    // If the next item fits exactly into the post_residual, reward this placement
    // (it sets up a perfect follow-up fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 35.0;
        } else if gap <= 15 {
            score -= 10.0;
        }
    }

    // --- Mean-residual alignment ---
    // Slightly prefer bins whose residual is close to the mean (avoid
    // fragmenting one very-full bin while others stay loose).
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    // --- Stream progression ---
    // Late in the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the smallest plausible
    // item size are pure waste; penalize them quadratically.
    if post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual < 25 {
        // Small unusable-ish gaps: mild quadratic penalty.
        let gap = 25.0 - post_residual as f64;
        score += 0.9 * gap * gap;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // Lookahead coupling: if the next item fits into the post residual,
    // this placement chains nicely; reward it. If next item is bigger than
    // post residual but this bin was the only option, that's a trap.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 18.0;
        } else if (post_residual as u32) > 0 {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (new bin candidate gets penalized via bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        let pressure = 40.0 + 6.0 * open_bins_count as f64;
        // But if the item is large and nothing fits well, new bin is fine.
        score += pressure;
    } else {
        // Slight preference for tighter existing bins.
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Late in the stream, consolidate harder: penalize spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but keep a floor so we
    // don't chase exact fits into pathological dead space.
    score = 0.6 * score + 20.0;

    // Aggressive 2-step lookahead: reward post_residual matching next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual == next_item_size {
