    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let w = 4.0 * progress * (1.0 - progress); // peaks mid-stream, 0 at ends
    score += w * (pr_norm * pr_norm) * 40.0;   // penalize large residuals mid-stream
    score -= w * (pr_norm * (1.0 - pr_norm)) * 25.0; // reward moderate residuals

    // Penalize very small dead space more sharply as stream progresses (quadratic in progress)
    if post_residual > 0 {
        score += (1.0 - progress) * (1.0 - progress) * (10.0 / pr);
    }

    // Perfect fit bonus, stronger late in stream
    if post_residual == 0 {
        score -= 30.0 + 30.0 * progress;
    }

    // Last-chance bin: reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening bins unless residual is small or item huge
    if bin_residual == bin_capacity {
        score += 20.0 + 25.0 * progress - (item_size as f64 * 0.3);
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // Discourage divergence from mean residual (keep bins balanced)
    score += ((pr - mean_residual).abs() / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: which capacity fraction band it lands in.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Dead-space penalty: residuals in (0, 10) are nearly unusable (min item size ~10 in
    // classic streams, but sizes 1..100 here -> treat < 16 as a "trap" class).
    if post_residual > 0 && post_residual < 16 {
        score += 60.0;
    }
    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Class-based reward: residual exactly divisible into large harmonics is reusable.
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 25.0;
    } else if post_residual % 25 == 0 && post_residual > 0 {
        score -= 12.0;
    } else if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Penalize landing in the awkward (eighth, quarter) band: too big to waste, too small
    // for many future items.
    if post_residual > eighth && post_residual < quarter {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / c);
        } else {
            // next item can't use this bin: mild penalty proportional to wasted opportunity
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin should only win when the fit is bad.
    if bin_residual == bin_capacity {
        score += 30.0;
        // If item is small relative to capacity, opening fresh is wasteful.
        if (item_size as f64) < 0.5 * c {
            score += 20.0;
        }
        // Early in the stream, opening bins is cheaper; late, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * (1.0 - progress);
    }

    // Prefer bins tighter than the mean residual (best-fit flavor with context).
    score += 0.3 * (pr - mean_residual);

    // Crowding bonus: with many open bins, favor filling existing ones.
    score -= 0.5 * open_bins_count as f64;

    // Item-size harmonic class: large items should be placed greedily into tight bins.
    let item_class = item_size / 20; // 0..5 harmonic buckets
    score -= 3.0 * item_class as f64 * (1.0 - pr / c);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for any plausible
    // future item (<= 10) are pure waste; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Gaps that can only fit the smallest items are semi-dead space.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }
    // Perfect or near-perfect fills are highly desirable.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward tight fits relative to the current residual (fill ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing bins rather than spreading out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 4.0 * pressure * (1.0 - fill_ratio);

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this
    // placement (chaining placements into one bin).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }
    // If the next item barely misses the post residual, penalize leaving
    // a gap that is almost-but-not-quite usable.
    if next_item_size > post_residual && post_residual > 0 && next_item_size > 0 {
        score += 8.0 * (1.0 - (next_item_size - post_residual) as f64 / 20.0).max(0.0);
    }

    // Mean residual coupling: prefer bins whose residual is below average
    // (tighter bins), keeping loose bins available for larger future items.
    score += 0.3 * (mean_residual - bin_residual as f64).max(-50.0);

    // New-bin candidate handling: an empty bin is a fallback; make it
    // attractive only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced when item is large
        // (large items are hard to place anyway).
        score = 25.0 - 0.15 * item_size as f64;
        // If the only fitting open bin leaves a big dead gap, a new bin
        // becomes competitive.
        if fitting_bins_count == 1 && post_residual > 40 {
            score -= 15.0;
        }
        // Early in the stream, opening bins is cheaper.
        score -= 10.0 * (1.0 - progress);
        // Many open bins with slack: discourage yet another bin.
        if mean_residual > 30.0 {
            score += 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: low post_residual is good.
    score -= 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // 2-step lookahead: reward if the next item fits into post_residual exactly or well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            // Perfect 2-chain: post_residual exactly consumed by next item.
            if gap == 0 {
                score -= 30.0;
            } else {
                score -= 15.0 * (1.0 - gap as f64 / bin_capacity as f64);
            }
        } else {
            // Next item cannot follow: penalize proportionally to the wasted chain potential.
            score += 6.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += 2.0 * (post_residual as f64 - mean_residual) / bin_capacity as f64;

    // Last-chance bin: strongly favor using the only bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when current bin would leave a large awkward gap.
    if bin_residual == bin_capacity {
        // Perfect single-item fit in fresh bin.
        if item_size == bin_capacity {
            score -= 50.0;
        }
        // Opening new bin is bad if any open bin fits reasonably; discourage by default.
        score += 10.0 + 0.05 * open_bins_count as f64;
        // But if the item is large relative to capacity, a fresh bin keeps flexibility.
        score -= 8.0 * item_size as f64 / bin_capacity as f64;
        // Late in the stream, avoid opening bins unless truly needed.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * progress;
    }

    // Penalize creating dead space smaller than the minimum item size (unusable gap).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: exact or near-exact fits are excellent.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space that nothing in the typical size range can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 8.0 * (next_item_size as f64 / 100.0);
        } else {
            score += 6.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the item
    // is large relative to remaining space and existing bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        let penalty = 55.0
            - 25.0 * (item_size as f64 / bin_capacity as f64)
            - 20.0 * fragmentation
            - 15.0 * (1.0 - progress);
        score += penalty.max(0.0);
    }

    // Mild preference for filling bins that are already heavily loaded,
    // keeping the number of open bins low.
    let load = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 10.0 * load;

    // Global pressure: many open bins with high mean residual -> consolidate.
    if open_bins_count > 2 && mean_residual > 30.0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let fill = 1.0 - (post_residual as f64) / cap;

    // Reward tight fits (small post_residual) with a smooth polynomial bonus
    let tightness = fill * fill;
    score -= 18.0 * tightness * (1.0 + 0.5 * progress);

    // Penalize dead space: very small residuals are hard to reuse
    let dead = if post_residual < item_size { 1.0 } else { 0.0 };
    // smooth surrogate for dead-space risk based on ratio
    let reuse_risk = (post_residual as f64 / cap).powi(3);
    score += 10.0 * reuse_risk * (1.0 - dead);

    // Lookahead coupling: if next item fits the post residual, reward
    if next_item_size > 0 {
        let next_fits = (next_item_size as f64) <= (post_residual as f64);
        let proximity = 1.0 - ((next_item_size as f64) - (post_residual as f64)).abs() / cap;
        let coupling = proximity.max(0.0);
        let term = if next_fits { -1.0 } else { 0.5 };
        score += 14.0 * term * coupling * coupling * (0.5 + progress);
    }

    // Last-chance bonus: only one bin can fit the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Mild penalty for spreading across many bins relative to mean residual
    score += 0.05 * open_bins_count as f64 * (1.0 - fill);
    score -= 3.0 * ((mean_residual - post_residual as f64) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue classes modulo 10 (capacity fraction classes)
    let post = post_residual as i64;
    let class = post % 10;
    // Perfect-fill classes are small residues (dead space nearly zero)
    match class {
        0 => score -= 25.0,               // exact fill -> perfect
        1 | 2 | 3 => score -= 12.0,       // near-perfect dead space
        4 | 5 | 6 => score -= 4.0,        // usable by small items
        _ => {}                            // 7..9 larger dead space, no reward
    }

    // Integer-division thresholds: post_residual / 10 buckets
    let bucket = post / 10;
    score += (bucket as f64) * 2.5; // penalize large leftover linearly a bit more

    // Lookahead coupling: can next item fit in post_residual?
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            // next item fits: reward proportional to tightness of that fit
            let tight = (next_item_size as f64) / cap;
            score -= 18.0 * tight;
            // harmonic class of the residual after a hypothetical next placement
            let post2 = post - next_item_size as i64;
            if post2 % 10 == 0 { score -= 15.0; }
            else if post2 % 10 <= 3 { score -= 7.0; }
        } else {
            // next item cannot fit: penalize more if residual is awkwardly large
            if post > 10 && post < next_item_size as i64 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so it's
    // chosen only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 40.0 + (open_bins_count as f64) * 0.5;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins)
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    // Stream progression: late in stream, be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - (post_residual as f64) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps below the minimum item size are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver -> heavy penalty
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight-fit bonus: reward small usable residuals proportionally.
    if post_residual > 0 && post_residual <= 20 {
        score -= 15.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Penalize leaving a residual that next item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Reward when the next item exactly fits the leftover.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Open-bin pressure: discourage scattering across many bins; encourage filling existing bins.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        score += 35.0 + mean_residual * 0.3;
    }

    // Slight preference to place into bins with below-average residual (more wasted bins get filled).
    if bin_residual != bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score -= diff * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
