}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tight = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tight * tight * 40.0;

    // Penalize bins with much larger residual than needed (wasted space).
    let slack = bin_residual as f64 - item_size as f64;
    if slack > 0.0 {
        score += (slack / bin_capacity as f64).powf(1.5) * 30.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 12.0 * (next_item_size as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize leaving awkward small residue.
        score += 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Time horizon: early in the stream, prefer consolidating into open bins
    // (many future items benefit from large residuals); later, be greedier.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 * (open_bins_count as f64).ln().max(0.0);
    score += progress * 8.0 * (post_residual as f64 / bin_capacity as f64);

    // Global residual pressure: if mean residual is low, opening new bins is
    // relatively attractive; if mean residual is high, prefer filling existing.
    score += 0.05 * (mean_residual - post_residual as f64);

    // New-bin candidate: only attractive when item is large relative to capacity
    // or no good existing option (handled via base score); add mild penalty so
    // fresh bins are chosen only for poor fits elsewhere.
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * (item_size as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted space, with non-linear growth for small residuals
    let mut score = pr + 40.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * pr;

    // Smooth coupling of post_residual with stream progress:
    // late in stream, tight fits (low post_residual) matter more
    let tightness = 1.0 - norm_pr;
    let progress_coupling = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score -= 60.0 * progress_coupling * tightness * tightness;

    // Lookahead: reward residual that can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let fit_quality = 1.0 - (pr - nxt) / cap;
            score -= 25.0 * fit_quality * fit_quality * (1.0 - progress_coupling);
        } else {
            score += 20.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 80.0 * (1.0 + progress_coupling);
    }

    // Penalize spreading when many bins are open and mean residual is high
    let mean_gap = (mean_residual - pr) / cap;
    score += 15.0 * mean_gap * mean_gap.abs();

    // Mild pressure to consolidate early, open new bins late
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact fit is best, small dead space worst.
    let post_class = post_residual / 10; // 0..10 classes
    match post_class {
        0 => score -= 30.0,                       // perfect fit
        1 => score += 12.0,                       // dangerous 1-10 dead space
        2 | 3 => score += 4.0,                    // small awkward residue
        4 | 5 => score += 0.0,                    // mid classes neutral
        6 | 7 => score -= 3.0,                    // half-bin residues reusable
        _ => score -= 1.0,                        // large residue, still flexible
    }

    // Reward bins whose residual class matches the next item's class (harmonic pairing).
    if next_item_size > 0 {
        let next_class = (next_item_size - 1) / 10;
        let post_class2 = post_residual / 10;
        if post_class2 == next_class && post_class2 >= 1 {
            score -= 6.0;
        }
        // Penalize leaving residue that next item almost-but-not-quite fits.
        if next_item_size > post_residual && next_item_size - post_residual <= 5 {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Crowding: with many open bins, prefer tightening existing bins over spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowd = open_bins_count as f64 / (1.0 + mean_residual / cap.max(1.0));
    score += crowd * 0.4 * (0.5 + progress);

    // Tightness bonus relative to mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is bad or bin is empty-ish.
    if bin_residual == bin_capacity {
        // New bin: good if item is large or no good fit exists.
        let large_item = item_size as f64 > 0.6 * cap;
        if large_item || (fitting_bins_count <= 1 && post_residual <= 10) {
            score -= 10.0;
        } else {
            score += 20.0;
        }
    }

