        } else if post_residual % 25 == 0 {
            score -= 12.0;
        } else if post_residual % 10 == 0 {
            score -= 6.0;
        }
    }

    // Awkward band: too big to waste, too small for many items.
    let eighth = bin_capacity / 8;
    let quarter = bin_capacity / 4;
    if post_residual > eighth && post_residual < quarter {
        score += 15.0;
    }

    // Fill ratio: tight fits rewarded.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Open-bin pressure: consolidate when many bins are open.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 4.0 * pressure * (1.0 - fill_ratio);

    // Last-chance bin: avoid opening a new bin when only this one fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead chaining.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / c);
        } else {
