        next_item_size
    } else {
        10
    };
    if post_residual < min_useful {
        // Dead space: escalate penalty the closer it is to a total waste.
        score += (min_useful - post_residual) as f64 * 3.0 + 20.0;
    } else if post_residual == 0 {
        // Perfect fit: strongly reward closing the bin.
        score -= 50.0;
    } else {
        // Usable gap: mild quadratic penalty to prefer tighter fits.
        score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 4.0);
    }

    // Reward fitting into bins that are already quite full (low residual waste).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins rather than opening new ones.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
