        score -= 15.0;
    }

    // New-bin candidate: make the empty bin attractive only when the current
    // item would leave a very poor gap in any existing bin, or few bins are open.
    if bin_residual == bin_capacity {
        let gap_penalty = if post_residual < min_useful { 1.0 } else { 0.0 };
