        score -= gap_penalty * 30.0 - pressure * 10.0 + 5.0;
        // Slightly favor new bin early in the stream when mean residual is high.
        score -= (mean_residual / bin_capacity as f64) * 3.0;
    }

    // Lookahead: if next item exactly fits the post-residual, strongly prefer this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; slight penalty for stranding it.
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-perfect match (small slack that is likely unusable).
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 10.0 {
            score -= 30.0 - 2.5 * slack;
        } else {
            // Dead space: leftover too small for the next item.
            score += slack * 0.35;
        }
    }

    // Last-chance bonus: only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize bins with small residuals relative to mean (fragmented bins),
    // unless it's the new-bin candidate.
    let is_new_bin = bin_residual == bin_capacity;
    if !is_new_bin {
        let rel = post_residual as f64 / bin_capacity as f64;
        // Reward tight packing: small relative residual.
        score -= (1.0 - rel) * 10.0;
        // Penalize residual below typical next item size (unusable sliver).
        if next_item_size > 0 && post_residual < next_item_size {
            score += 15.0;
        }
    } else {
        // New bin: attractive early in the stream or when current bin fits poorly,
        // but generally discouraged when a decent fit exists.
