        new_bin_score += 20.0 * (1.0 - progress);
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // Room for the next item too: mildly attractive.
            new_bin_score -= 8.0;
        }
        if fitting_bins_count > 2 {
            // Plenty of alternatives: discourage opening a new bin.
            new_bin_score += 30.0;
        }
        score = new_bin_score;
    }

    score
