    // Time horizon: early in the stream, be more willing to open new bins
    // (long future to use them); late, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize late in the stream, cheaper early.
        score += 15.0 * progress + 3.0;
    } else {
        score -= 2.0 * progress;
    }

    score
}

