pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post-residual, with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth progress coupling: later in stream, penalize residual waste more strongly
    let progress_coupling = 1.0 + 1.5 * progress * (1.0 - 0.5 * progress);
    score *= progress_coupling;

    // Interaction: post_residual vs mean residual — bins below mean residual are better to fill
    let mean_gap = (mean_residual - pr) / cap;
    score += 20.0 * mean_gap * mean_gap;

    // Last-chance bonus: smooth reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - norm_pr);
    }

    // Perfect fit reward (smooth, quadratic decay toward zero residual)
    score -= 15.0 * (1.0 - norm_pr).powi(3);

    // Lookahead: penalize if post-residual can't fit next item (smoothly)
    if next_item_size > 0 {
        let fits_next = if (pr as u32) >= next_item_size { 1.0 } else { 0.0 };
        let slack = ((pr as u32).min(next_item_size) as f64 / next_item_size.max(1) as f64);
        score -= 10.0 * fits_next * slack;
        score += 8.0 * (1.0 - fits_next) * (norm_pr + 0.1);
    }

    // Mild penalty for spreading across too many open bins
    score += 0.3 * open_bins_count as f64 * norm_pr;

    score
}

