pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the smallest plausible
    // item size are pure waste; penalize them quadratically.
    if post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual < 25 {
        // Small unusable-ish gaps: mild quadratic penalty.
        let gap = 25.0 - post_residual as f64;
        score += 0.9 * gap * gap;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // Lookahead coupling: if the next item fits into the post residual,
    // this placement chains nicely; reward it. If next item is bigger than
    // post residual but this bin was the only option, that's a trap.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 18.0;
        } else if (post_residual as u32) > 0 {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (new bin candidate gets penalized via bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        let pressure = 40.0 + 6.0 * open_bins_count as f64;
        // But if the item is large and nothing fits well, new bin is fine.
        score += pressure;
    } else {
        // Slight preference for tighter existing bins.
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Late in the stream, consolidate harder: penalize spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    score
