pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // matches the next item size (perfect chain), penalize dead space the
    // next item cannot use.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post == nxt {
            // Perfect 2-chain: next item fills this bin exactly.
            score -= 120.0;
        } else if post >= nxt {
            // Next item still fits after this one; mildly reward small leftover.
            score -= 25.0 * (1.0 - (post - nxt) / bin_capacity as f64);
        } else {
            // Dead space: next item cannot use the leftover; penalize
            // proportionally to how wasted the space is.
            score += 30.0 * (1.0 - post / nxt);
        }
        // Bonus if the chain closes the bin completely after two placements.
        if post == nxt && post_residual == 0 {
            score -= 40.0;
        }
    }

    // Tight fit reward: placing this item leaves little residual.
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 20.0 * tightness * tightness;

    // Penalize very small unusable residuals (classic dead space trap).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless the lookahead suggests a perfect new-bin chain).
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Prefer bins with below-average residual (concentrate fragmentation),
    // which keeps large residuals available for large future items.
    score -= 8.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;

    // New-bin candidate baseline: neutral-ish score that scales with stream
    // progress and open-bin count; only chosen when open bins score badly.
    if bin_residual == bin_capacity {
        score = 55.0 + 20.0 * (step_index as f64 / total_items.max(1) as f64) + 2.0 * open_bins_count as f64;
        // If lookahead shows next item is large, opening fresh is more attractive.
        if next_item_size >= 50 {
            score -= 15.0;
        }
        if next_item_size > 0 && (bin_capacity as f64 - item_size as f64 - next_item_size as f64).abs() < 1.0 {
            score -= 100.0; // fresh bin perfectly fits current+next
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose post residual is small.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 8.0 * tightness * tightness;

    // Lookahead: reward bins where the next item can also fit (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_quality = (post_residual - next_item_size) as f64 / cap;
        score -= 4.0 * (1.0 - chain_quality);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Penalize creating dead space the lookahead item cannot use.
        let dead = (next_item_size - post_residual) as f64;
        score += 0.08 * dead;
    }

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual < 10 {
        score -= 6.0;
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: penalize opening a new bin mildly,
    // scaled by how "wasteful" it would be (large post residual in new bin)
    // and by stream progress (later in stream, prefer consolidation).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 6.0 + 8.0 * progress;
        // But if the item is large, a fresh bin is natural; soften penalty.
        score -= 0.05 * item_size as f64;
    }

    // Mild penalty when this bin's residual is far above the mean
    // (keeps residuals homogeneous, leaving small bins for small items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.02 * dev;

    // Slight preference for consolidating into already-open bins
    // when many bins are open (avoid bin proliferation).
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
