    if next_item_size > 0 {
        let fits_next = if (pr >= next_item_size as f64) { 1.0 } else { 0.0 };
        let slack = (pr - next_item_size as f64).abs();
        score -= fits_next * (1.0 - slack / cap) * 6.0;
        // penalize near-miss residuals that block the next item
        let near_miss = (1.0 - fits_next) * (1.0 - (slack / cap).min(1.0));
        score += near_miss * 4.0;
    }

    // Last-chance bonus: strongly prefer using a bin when it's the only fitting one
    if fitting_bins_count == 1 {
        score -= 8.0;
