    // Mild penalty for spreading across many open bins relative to mean residual
    score += (open_bins_count as f64).ln() * (mean_residual - pr).abs() * 0.02;

    // New-bin candidate: empty bin should lose unless residuals of open bins are poor
    if bin_residual == bin_capacity {
        score += 3.0 + mean_residual * 0.05;
    }

    score
}

