    let bucket = (post_residual / 10) as f64;
    score += bucket * 0.35;

    // Dead-space penalty: residuals that cannot host the smallest item class are bad.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Harmonic compatibility: does post_residual align (modulo) with next_item_size?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            // Next item fits exactly into a harmonic slot of this residual.
            let m = post_residual % next_item_size;
            if m == 0 {
                score -= 12.0; // perfect modular fill
            } else if m < 10 {
                score += 4.0; // near-miss creates small dead space
            } else {
                score -= 3.0; // reusable remainder
            }
            // Reward if next item can fit (residual stays usable).
            score -= (nxt / cap) * 6.0;
        } else {
            // Next item won't fit here; penalize proportionally to wasted potential.
            score += 6.0;
        }
    }

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Tightness reward: prefer bins where the item fills a large fraction of residual.
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_frac * 10.0;

    // Prefer fuller bins (small residual before placement) mildly.
    score += (bin_residual as f64 / cap) * 4.0;

    // New-bin candidate: only attractive late in stream or when current fit is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = post_residual as f64 > cap * 0.5;
        score += 18.0 - progress * 10.0;
        if poor_fit {
            score -= 14.0;
        }
        if next_item_size > 0 && next_item_size as f64 > cap * 0.7 {
            score -= 8.0; // keep a fresh bin for a big upcoming item
        }
    }

    // Mean-residual coupling: when open bins are generally empty, discourage spreading.
    if mean_residual > cap * 0.6 && bin_residual != bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold any
    // future item (min item size 1..100 unknown, assume small items >= 10)
    // are wasted. Penalize the "unusable gap" zone harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + 8.0 * (10 - post_residual) as f64;
    }
    // Near-perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward bins whose residual tightly matches the item (good fit ratio).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin_penalty = 8.0 + 30.0 * (open_bins_count as f64 / 10.0).min(1.0) + 10.0 * progress;
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
        // Opening a new bin is fine if the next item is large and this item is small.
        if next_item_size >= 60 && item_size <= 20 {
            score -= 25.0;
        }
    } else {
        score -= new_bin_penalty * 0.15;
    }

    // Lookahead: prefer leaving residual that can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // Mild preference for bins below mean residual (consolidate waste).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

