pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let post = post_residual as f64;
    let next = next_item_size as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mean_r = mean_residual.max(0.0);

    // --- Exact fill: bin closes completely (best possible outcome) ---
    if post_residual == 0 {
        score -= 600.0 + item_size as f64 * 0.5;
    }

    // --- Aggressive 2-step lookahead against next_item_size ---
    if next > 0.0 {
        if post_residual == next_item_size {
            // Perfect 2-item match: bin becomes exactly full after the next item
            score -= 400.0 + next * 0.5;
        } else if post_residual > next_item_size {
            // Next item can chain into the leftover space of this bin
            score -= next * 0.6;
        } else if post_residual > 0 {
            // Stranded leftover below the next item's scale: penalize the near-miss.
            // Amplified when mean residual is low (little slack elsewhere to absorb future items).
            score += (next - post) * (30.0 / (30.0 + mean_r));
        }
    }

    // --- Coupling with mean residual across open bins ---
    if post > mean_r {
        // Looser than the fleet average: discourage digging into roomy bins
        score += (post - mean_r) * 0.15;
    } else {
        // Tighter than average: reinforce the best-fit preference
        score -= (mean_r - post) * 0.05;
    }

    // --- Last-chance bin: only open bin that can fit this item ---
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 150.0;
    }

    // --- New-bin candidate: only wins when open-bin fits are genuinely poor ---
    if is_new_bin {
        score += 15.0
            + open_bins_count as f64 * 0.3   // fragmentation pressure
            + mean_r * 0.1                   // slack already spread across open bins
            + progress * 40.0;               // late-stream new bins have no time to fill
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: penalize large post_residual with a convex term
    let pr = post_residual as f64;
    score += 0.15 * (pr / bin_capacity as f64) * (pr / bin_capacity as f64) * bin_capacity as f64;

    // Lookahead coupling: if the next item fits the post-residual exactly-ish, reward this bin
    if next_item_size > 0 {
