    let pressure = open_bins_count as f64 * mean_residual / (bin_capacity as f64 * 10.0);
    score -= 8.0 * pressure * (1.0 - progress);

    // Late in stream: avoid opening new bins; penalize the fresh-bin candidate
    if bin_residual == bin_capacity {
