pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: harmonic class of post-residual
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual <= 10 {
        score -= 40.0; // near-perfect, dead space minimal
    } else if post_residual <= 20 {
        score -= 15.0;
    }

    // Harmonic classes via integer division: post_residual bucket
    let bucket = post_residual / 10; // 0..=10 classes
    score += (bucket as f64) * 3.0;

    // Next-item lookahead: penalize residuals that cannot host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // can host next item: reward proportionally to how snugly
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // dead space relative to next item: penalize modulo mismatch
            let mismatch = (next_item_size - post_residual) % 100;
            score += 8.0 + (mismatch as f64) * 0.15;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Avoid wasting a nearly-full bin's identity vs new bin: new-bin candidate gets a mild penalty
    if bin_residual == bin_capacity {
        score += 5.0;
        // opening a new bin is fine if mean residual across open bins is small (fragmented state)
        score -= (mean_residual / bin_capacity as f64) * 10.0;
    }

    // Prefer filling bins with high residual (reduce fragmentation) when many bins open
    score -= (bin_residual as f64 / bin_capacity as f64) * (open_bins_count as f64).sqrt() * 2.0;

    // Late-stream consolidation: as stream progresses, favor tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (100.0 - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "unusable" if it is smaller than the smallest plausible item (1)
    // but practically: gaps below ~10 (min size in classic streams) or below
    // the lookahead item are waste. Penalize a dead zone quadratically.
    let dead_threshold = 12u32;
    if post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 8.0;
    }

    // If the leftover cannot host the lookahead item, penalize proportionally.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 3.0;
        } else {
            // Reward leaving room for the next item (chaining placements).
            score -= 4.0;
        }
