    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 20.0;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage opening a new one.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins and mean slack.
        score += 30.0 + (open_bins_count as f64 * 2.5) + mean_residual * 0.3;
        // Opening a new bin is acceptable if the current item is huge and would
        // strand tiny dead space in every existing bin — already captured above.
    } else {
        // Using an existing bin slightly relieves pressure as the stream matures.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 3.0;
    }

    // Mild penalty when this bin's residual is far below the mean (hoarding slack).
    if (bin_residual as f64) < mean_residual - 20.0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // perfect 2-step chain closure
        } else if post_residual > next_item_size {
            score -= 18.0 - 0.15 * (post_residual - next_item_size) as f64;
        } else {
            // next item cannot use this bin's remainder: penalize dead space
            score += 0.6 * (next_item_size - post_residual) as f64;
        }
    }

    // Tight fit reward relative to capacity
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill_ratio;

    // Penalize residuals that few future items could use (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable slivers
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // New-bin candidate bias: make fresh bins slightly less attractive unless
    // current bins are nearly full (encourages consolidation early on).
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - fill_ratio);
        // but if no open bin fits well, allow opening
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Late in stream: be more conservative, avoid fragmentation
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: penalize large relative waste.
    let waste_ratio = post_residual as f64 / cap;
    score += waste_ratio * waste_ratio * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: favor bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0 * (1.0 - t * 0.5);
    } else if next_item_size > 0 && post_residual > 0 {
        // leftover too small for next item: penalize dead space more late in stream
        score += 10.0 + 15.0 * t;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let avg_fit_quality = (mean_residual - item_size as f64).abs();
        score = cap * 0.55 + avg_fit_quality * 0.3 + open_bins_count as f64 * 0.5;
        if fitting_bins_count == 0 {
            score -= 80.0; // must open a bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 12.0; // big item likely followed by another big one
        }
    }

    // Slight preference for fuller bins overall.
    score -= (bin_residual as f64 - mean_residual) * 0.15;

    // Late-stream consolidation pressure.
    score += t * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;
    let tight = (fill * fill * (3.0 - 2.0 * fill)).clamp(0.0, 1.0);

    // Base: prefer small post-residual, with smooth polynomial sharpening over stream progress
    let mut score = pr * (1.0 + 0.8 * progress * tight);

    // Smooth penalty on large dead space, growing late in the stream
    let dead = pr / cap;
    score += 12.0 * dead * dead * dead * (0.3 + 0.7 * progress);

    // Reward near-perfect fits smoothly
    score -= 15.0 * tight * tight * (item_size as f64 / cap);

    // Lookahead coupling: if next item fits the post-residual exactly-ish, reward
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        let gap_n = gap / cap;
        score -= 8.0 * (1.0 - gap_n) * (1.0 - gap_n) * pr / cap;
    }

    // Last-chance bin: smooth bonus when few fitting bins
    if fitting_bins_count <= 1 {
        score -= 6.0 * tight;
    }

    // Mild preference for consolidating into fewer bins when mean residual is small
    score += 0.05 * (mean_residual - pr).abs() * (1.0 - progress);

    // New-bin candidate: penalize slightly unless current post-residual is very tight
    if bin_residual == bin_capacity {
        score += 4.0 + 10.0 * (1.0 - tight);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with non-linear sharpening
    let fit_ratio = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * fit_ratio * fit_ratio;

    // Harmonic class of post_residual: dead-space classes
    // Residuals that are multiples of 20 (capacity/5) are "harmonic" and reusable.
    let pr = post_residual;
    if pr > 0 {
        let harmonic = pr % 20 == 0 || pr % 25 == 0;
        if harmonic {
            score -= 6.0; // residual aligns with common item sizes -> keep it
        } else if pr < 10 {
            score += 8.0; // unusable dead space (items >= 10 or 1..100 worst case)
        } else if pr < 20 {
            score += 3.0; // marginal dead space
        }
    } else {
        score -= 10.0; // perfect closure
    }

    // Integer-division threshold classes on post_residual
    let class = pr / 25; // 0: tiny, 1: small, 2: medium, 3: large
    score += 2.5 * class as f64;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / 40.0).max(0.0);
        } else {
            // next item won't fit here; penalize leaving large-but-broken residuals
            score += 1.5;
        }
    }

    // Last-chance bonus: only this bin can fit the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets neutral base but should only win
    // when all open bins are poor fits.
    if bin_residual == bin_capacity {
        score = 55.0
            + 0.05 * (open_bins_count as f64)
            + (mean_residual - fit_ratio * 100.0).abs() * 0.02;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced new bin
        }
        if next_item_size > 0 && next_item_size <= bin_capacity && next_item_size >= item_size {
            score -= 2.0; // slight preference when next item is bigger
        }
    }

    // Stream progression: late in stream, prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * progress * (post_residual as f64 / 100.0);

    // Mild penalty for spreading across many open bins
    score += 0.03 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized (dead space), while usable gaps are fine.
    let min_useful = 10.0_f64; // smallest conceivable future item footprint
    if (post_residual as f64) < min_useful && post_residual > 0 {
        // Perfect fit (post_residual == 0) is ideal; tiny leftovers are dead space.
        score += (min_useful - post_residual as f64) * 8.0;
    }

    // Reward tight fits superlinearly: the closer post_residual is to 0,
    // the better (as long as it is not a tiny dead gap, handled above).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 12.0;

    // Pressure from number of open bins: discourage spreading across many
    // open bins; prefer consolidating into existing bins when many are open.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: opening a fresh bin should only win when the fit in
    // existing bins would be poor. Penalize the empty bin moderately.
    if bin_residual == bin_capacity {
        score += 35.0 + mean_residual * 0.3;
    } else {
        // Slight bonus for bins that are already partially filled relative
        // to the mean residual (prefer fuller bins).
        score += (mean_residual - bin_residual as f64) * 0.4;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this placement strongly (chain fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            // Next item cannot use the leftover: mild penalty proportional
            // to how much would be wasted.
            score += (post_residual as f64) * 0.15;
        }
    }

    // Stream progression: early on, be more willing to open bins; later,
    // consolidate aggressively to close gaps.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits the post-residual exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= 50.0;
        } else {
            // next item cannot fit here: penalize leaving medium dead space
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Compare post_residual relative to mean residual: keep residuals balanced
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Penalize new empty bin slightly, unless current bins leave bad fits
    if bin_residual == bin_capacity {
        score += 20.0;
        // If lookahead shows a big next item, opening a fresh bin is attractive
        if next_item_size > post_residual && next_item_size >= bin_capacity / 2 {
            score -= 150.0;
        }
    }

    // Small penalty for very tight but nonzero residuals (dead space risk)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits strongly (non-linear).
    let tightness = 1.0 - post / cap;
    score -= tightness * tightness * 30.0;

    // Penalize dead space: post-residuals too small for typical future items.
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (10.0 - post);
    }

    // Lookahead coupling: if next item fits into post-residual, reward heavily.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            score -= 20.0 + 10.0 * (1.0 - (post - nx) / cap);
        } else {
            // Wasted capacity relative to next item.
            score += (nx - post).min(cap) * 0.4;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Many open bins: prefer consolidation into existing bins (penalize new bins).
    if bin_residual == bin_capacity {
        score += 40.0 + open_bins_count as f64 * 3.0;
        // Early in stream, opening new bins is cheaper; late, expensive.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 30.0 - progress * 20.0;
    }

    // Global residual pressure: high mean residual means slack exists; use it.
    score += (mean_residual - post) * 0.15;

    // Prefer filling bins with larger residuals first (best-fit-ish), softened.
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.05;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap; // fraction of bin filled after placement
    let fit_ratio = item_size as f64 / bin_residual as f64;

    let mut score = pr;

    // Smooth polynomial coupling: reward high fill more strongly as stream progresses
    let fill_poly = fill * fill * (2.0 - fill);
    score -= 30.0 * fill_poly * (0.5 + progress);

    // Penalize small-but-nonzero dead space quadratically (unusable slivers)
    let dead = pr / cap;
    score += 25.0 * dead * dead * (1.0 - dead);

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: reward if next item fits the post residual smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = if pr >= nx { 1.0 } else { 0.0 };
        let tight = (pr - nx) / cap;
        score -= 15.0 * fits_next * (1.0 - tight * tight);
        score += 8.0 * (1.0 - fits_next) * dead;
    }

    // Mild penalty for spreading across many open bins vs consolidating
    score += (open_bins_count as f64).ln() * 2.0 * (1.0 - fill);

    // Prefer tighter fits (high fit_ratio) with smooth reward
    score -= 10.0 * fit_ratio * fit_ratio;

    // New-bin candidate: keep it neutral-to-slightly-worse unless residuals are bad
    if bin_residual == bin_capacity {
        score = pr + 5.0 - 10.0 * (1.0 - (mean_residual / cap).min(1.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Exact fit: perfect packing class.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Harmonic class of post_residual: residues divisible by small integers
    // are more likely reusable by future items (common sizes 10..80).
    let pr = post_residual;
    let reusability: f64 = {
        let mut r = 0.0;
        if pr >= 10 && pr % 10 == 0 { r += 6.0; }        // decade class
        if pr >= 20 && pr % 20 == 0 { r += 4.0; }        // 20-class
        if pr >= 25 && pr % 25 == 0 { r += 3.0; }        // quarter class
        if pr >= 50 && pr % 50 == 0 { r += 2.0; }        // half class
        if pr >= 30 && pr % 30 == 0 { r += 1.5; }
        r
    };
    score -= reusability;

    // Penalize dead space: post_residual too small for ANY item (min size 1)
    // but too small for likely items (below 10) is stranded waste.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward; if next item cannot fit, mild penalty.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            // harmonic match: next item divides or is near-divisible by post residual
            let gap = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - gap / cap);
            if post_residual % next_item_size.max(1) == 0 {
                score -= 10.0;
            }
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only prefer a fresh bin if all open bins
    // would strand large dead space relative to mean residual.
    if bin_residual == bin_capacity {
        let pressure = (mean_residual - item_size as f64) / cap;
        if pressure > 0.3 && fitting_bins_count > 0 {
            score += 60.0 + 50.0 * pressure; // discourage new bin when open bins fit well
        } else {
            score -= 20.0; // encourage fresh bin when open bins are poor
        }
    }

    // Fraction-of-capacity classes: reward placements leaving residual in
    // "friendly" fraction bands (1/4, 1/2, 3/4 of capacity).
    let frac = post / cap;
    if (frac - 0.25).abs() < 0.02 { score -= 12.0; }
    if (frac - 0.5).abs() < 0.02 { score -= 12.0; }
    if (frac - 0.75).abs() < 0.02 { score -= 12.0; }

    // Mild fill-progress reward scaled by stream progression.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (item_size as f64 / cap) * (10.0 + 10.0 * progress);

    // Penalize opening many bins with large mean residual (fragmentation).
    if open_bins_count > 4 && mean_residual > 40.0 && bin_residual != bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
