pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect placement, heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Dead-space avoidance: penalize small unusable gaps more than proportionally.
    // A residual that no plausible item can fill is wasted space.
    let pr = post_residual as f64;
    if pr < 10.0 {
        // Tiny gap below the smallest typical item: severe dead space.
        score += 60.0 * (10.0 - pr);
    } else if pr < 30.0 {
        // Medium-small gap: moderate super-linear penalty.
        score += 0.8 * pr * (30.0 - pr) / 10.0;
    }

    // Reward residuals that can still host the lookahead item (k=2 lookahead synergy).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 15.0 * (1.0 - (pr - nxt) / 50.0).max(0.0);
        } else {
            // This bin cannot host the next item: mild penalty scaled by how close it is.
            score += 10.0 * (nxt - pr) / nxt;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (penalize the new-bin candidate which has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // New empty bin: penalize proportionally to how many bins are already open
        // and how much slack already exists across the fleet.
        score += 25.0 + 8.0 * open_bins_count as f64 + 0.3 * mean_residual;
        // But if the item is huge and would leave a terrible gap in any open bin,
        // a fresh bin is naturally competitive; leave base score intact otherwise.
    } else {
        // Slight preference for tighter bins among open ones (implicit in post_residual),
        // plus a mild reward for keeping open-bin count from growing.
        score -= 5.0;
    }

    // Progress-based calibration: late in the stream, waste matters more (less
    // opportunity to fill gaps later), so amplify dead-space penalties.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.25 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but keep a floor so we
    // don't chase exact fits into pathological dead space.
    score = 0.6 * score + 20.0;

    // Aggressive 2-step lookahead: reward post_residual matching next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual == next_item_size {
            // Perfect 2-step match: huge reward.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item could also fit here: proportional reward.
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Dead space relative to next item: penalize proportionally.
            score += 15.0 * (diff / bin_capacity as f64);
        }
        // Small bonus if next item fits in post_residual at all.
        if post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Compare against mean residual: bins with residual below mean are
    // "tighter" than average, favor them slightly.
    score -= 0.15 * (mean_residual - post_residual as f64);

    // Penalize leaving unusable slivers (< 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Mild preference for opening new bins early in the stream (more
    // flexibility later), decaying as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive baseline, discounted by progress.
        score = score * 0.5 + 10.0 * (1.0 - progress);
        // Don't open a new bin if a decent fit exists elsewhere.
        if post_residual == bin_capacity && item_size <= bin_capacity / 2 {
            score += 12.0;
        }
    }

    // Slight load-balancing: prefer bins with residual below mean when many
    // bins are open.
    if open_bins_count > 4 && (post_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual), but only if the leftover is not "dead space".
    let dead_threshold = 10.0_f64; // smallest plausible future item is ~1; treat tiny leftovers carefully
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 25.0; // penalize creating nearly-unusable slivers
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // When many bins can fit, prefer the one with best relative fit.
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 3.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 200.0;
        } else if post_residual >= next_item_size {
            // mild bonus proportional to how well next item fits after this placement
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here; penalize large wasted residuals mildly
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // New-bin candidate logic: only attractive when open bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline: a fresh bin has residual 100; make it less attractive than decent fits
        // but more attractive than terrible fits when open bins are fragmented.
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score -= 30.0 + fragmentation * 0.3;
        // Late in the stream, opening a new bin is less costly (no future to serve).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 20.0;
    }

    // Prefer filling bins that deviate below the mean residual (consolidate emptier bins).
    if !is_new_bin {
        let dev = mean_residual - bin_residual as f64;
        score -= dev * 0.4;
    }

    // Mild penalty for opening bins early when few bins exist (keep bin count low).
    if open_bins_count > 0 && is_new_bin {
        score += (open_bins_count as f64) * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let tightness = 1.0 - post / cap;

    // Base: penalize wasted space, quadratically so small dead space matters more late.
    let mut score = post * (1.0 + 0.8 * progress) + 0.35 * post * post / cap;

    // Smooth non-linear coupling of post_residual with stream progress.
    let wave = (progress * std::f64::consts::PI).sin();
    score += 6.0 * tightness * tightness * wave;

    // Lookahead: reward leaving room for the next item (smooth kernel).
    if next_item_size > 0 {
        let gap = post - next_item_size as f64;
        if gap >= 0.0 {
            score -= 9.0 * (1.0 - gap / cap).powi(2);
        } else {
            score += 4.0 * (-gap / cap);
        }
    }

    // Last-chance bin gets a bonus to avoid opening new bins unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 * (1.0 + progress);
    }

    // Slight preference for filling bins below mean residual (consolidation).
    score -= 0.05 * (mean_residual - post);

    // Penalize opening a new bin when good fits exist, more so early on.
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - 0.5 * progress) + 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer small post_residual, but heavily penalize unusable dead space.
    // Dead space = post_residual that cannot hold a "harmonic class" minimum item (size 1..=100, assume small items exist).
    // Classify post_residual into harmonic classes via integer division thresholds.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction band does it fall into?
    // Bands: [0..10] great, (10..25] good, (25..50] mediocre, (50..100] bad (wasted half-bin).
    let band = if post_residual <= 10 { 0.0 }
        else if post_residual <= 25 { 1.0 }
        else if post_residual <= 50 { 2.0 }
        else { 3.0 };
    score += band * 12.0;

    // Exact/near-exact fits are gold: reward strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead harmony: if next item fits into post_residual, big reward (chained packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 + slack * 0.1;
        // Perfect chain: next item leaves another tiny residual
        if post_residual - next_item_size <= 10 {
            score -= 15.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; mildly penalize if post_residual is large enough to be tempting but unusable.
        let gap = (next_item_size - post_residual) as f64;
        if gap <= 10.0 {
            score += gap * 0.8; // near-miss: painful dead space
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // unless the fit is terrible (huge post_residual waste).
    if fitting_bins_count == 1 {
        score -= 30.0;
        if post_residual > 50 {
            score += 20.0; // but don't stuff a huge item into a nearly-full bin scenario
        }
    }

    // New-bin candidate logic: an empty bin has post_residual == bin_residual == capacity.
    // Penalize opening a new bin unless existing bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = mean_residual / cap; // average fullness complement
