    // of 10 pair better with typical item sizes; reward them slightly.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Prefer filling bins with larger residual (big bins absorb big items well) when item is large.
    if item_size > bin_capacity / 2 {
        score += (bin_residual as f64 - item_size as f64) * 0.05;
    }

    // Slight preference for tighter bins overall (best-fit core).
    score += (bin_residual as f64 - post) * 0.02;

    score
}

