    // Global state coupling: many open bins with high mean residual -> prefer
    // filling existing bins over opening new ones.
    if open_bins_count > 0 {
        let crowding = mean_residual / bin_capacity as f64;
        if bin_residual < bin_capacity {
            score -= 10.0 * crowding;
        } else {
            // New-bin candidate: penalize when open bins are roomy on average,
            // reward when open bins are nearly full (fragmented).
            score += 20.0 * crowding - 15.0;
        }
    }

    // Mild penalty for leaving awkward medium dead space (unusable for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let poly = base * base * (1.0 + progress) + base * (1.0 - progress) * (1.0 - progress);

    let mut score = pr + 40.0 * poly;

    // Penalize bins whose residual deviates from the mean (fragmentation signal)
    let dev = (pr - mean_residual) / cap;
    score += 15.0 * dev * dev;

