    score -= 25.0 * (item_size as f64 / cap);

    // Last-chance bonus: only one fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Lookahead: favor leaving space usable by the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 8.0 * (1.0 - ((pr - nx) / cap).abs());
        } else {
