    }

    // New-bin candidate handling: opening a new bin wastes mean residual already open.
    if bin_residual == bin_capacity {
        // base reluctance to open a new bin
        score += 55.0;
        // if item is large, new bin is more attractive (avoids fragmentation)
        if item_size > bin_capacity / 2 {
            score -= 40.0;
        }
        // if no other bin fits, new bin is necessary
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // late in stream, prefer consolidating into existing bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mild penalty proportional to deviation from mean residual (prefer balanced fills).
    score += 0.08 * ((bin_residual as f64) - mean_residual).abs();

    // Slight preference for bins that are already fairly full (smaller residual).
    score += 0.05 * (bin_residual as f64);

    // Small tie-breaker by item size class (larger items placed first-ish).
    score -= 0.02 * (item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in [1, 15] is unusable junk -> heavy penalty.
    let pr = post_residual as f64;
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score += 45.0; // tiny dead space: worst outcome
    } else if post_residual < 16 {
        score += 25.0;
    } else if post_residual <= 20 {
        score -= 5.0; // residual 16..20 can still fit small items (min size 10)
    }

    // Reward tight fills (high fill ratio).
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer consolidation.
    score += 2.5 * open_bins_count as f64;

    // Prefer bins with residual below mean (consolidate small leftovers).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Lookahead: if next item fits the post-residual, reward; if it barely misses, penalize.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            score -= 8.0 * (ni / (pr + 1.0));
        } else if pr > 0.0 && ni - pr <= 10.0 {
            score += 10.0; // next item just misses: this residual likely dead
        }
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        let bad_fit = fitting_bins_count == 0
            || (fitting_bins_count == 1 && post_residual < 10);
        if bad_fit {
            score -= 25.0;
        } else {
            score += 35.0; // keep using existing bins when fit is decent
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        let post_f = post_residual as f64;
        if post_f >= next_f {
            let match_gap = post_f - next_f;
            // Strong reward if the next item fits perfectly here
            if match_gap == 0.0 {
                score -= 500.0;
            } else {
                // decayed reward for near matches
                score -= 200.0 / (1.0 + match_gap / 20.0);
            }
        } else {
            // next item cannot use this bin's leftover; penalize dead space
            score += (next_f - post_f).min(60.0) * 0.5;
        }
    }

    // Prefer tighter fits relative to the mean residual of open bins
    let post_f = post_residual as f64;
    if post_f > mean_residual {
        score += (post_f - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - post_f) * 0.1;
    }

    // Last-chance bin: avoid opening a new bin if this fits reasonably
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would waste a lot
    if bin_residual == bin_capacity {
        // neutral baseline slightly above a good fit
        score += 30.0;
        // early stream: be more willing to open bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 20.0;
        // if many open bins are fragmented, new bin is attractive
        if mean_residual < 30.0 {
            score -= 40.0;
        }
    }

    // Penalize creating small unusable slivers (< 10, the min item size historically)
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

