    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(100) {
        score += 40.0;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Prefer fuller bins (tight fit): smaller relative post residual favored
    score += (post_residual as f64 / bin_residual.max(1) as f64) * 30.0;

    // New-bin candidate: penalize opening a new bin unless item is large / fits are bad
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = item_size as f64 / bin_capacity as f64;
        let mut penalty = 90.0 + 200.0 * (1.0 - large_item);
        if fitting_bins_count == 0 {
            penalty -= 400.0; // no open bin fits -> opening is fine
        }
        if next_item_size > 0 && next_item_size >= item_size {
            penalty += 50.0 * progress; // late stream: avoid fragmentation
        }
        score += penalty;
    }

    // Global state: many open bins with high mean residual -> favor consolidating into bins
    score += 0.05 * mean_residual * (open_bins_count as f64).sqrt() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fill_ratio = 1.0 - post / cap;

    // Base: prefer minimal post residual, with non-linear (quadratic/cubic) waste penalty
    let mut score = post * (1.0 + 0.5 * fill_ratio * fill_ratio);

    // Smooth polynomial coupling of waste with stream progress:
    // waste matters more early (many future items to fill gaps), less late
    let early = (1.0 - progress) * (1.0 - progress);
    let late = progress * progress;
    score += 8.0 * early * (post / cap) * (post / cap);
    score -= 6.0 * late * fill_ratio;

    // Lookahead: penalize residual that cannot fit the next item (dead space),
    // reward residual that nicely accommodates it
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 10.0 * (1.0 - post / nxt) * (0.5 + late);
        } else {
            let snug = 1.0 - ((post - nxt) / cap);
            score -= 4.0 * snug * snug;
        }
