    // or few bins fit the item (avoid spreading small items into fresh bins)
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        score = cap - 30.0 * item_frac * item_frac - 5.0 * (fitting_bins_count as f64).min(3.0);
        score += 10.0 * late;
    }

    // Mild preference for bins tighter than the fleet average
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) strongly rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space classes: residuals that can only hold tiny items are bad.
        let class = post_residual / 10; // integer division thresholds: 0..10
