    }

    // Modulo-10 harmony: residuals divisible by 10 pair well with the 10-multiple grid.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead coupling: does next_item_size fit exactly in post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // chain a perfect follow-up fit
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            let slack_class = slack / 10;
            score -= 40.0 - (slack_class as f64) * 6.0;
            if slack % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // Next item cannot follow here; penalize slightly more when this bin is rare.
            score += 15.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count <= 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // New-bin candidate handling: empty bin gets a moderate default so real
    // placements with decent fits beat it, but terrible fits don't.
    if bin_residual == bin_capacity {
        score = cap * 0.55 + (item_size as f64) * 0.2;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin can host a growing sequence
        }
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative exists
        }
    }

    // Stream progression: early on, be pickier about waste (more future items to place).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * (post_residual as f64) * 0.15;

    // Mean residual context: if this bin is far below mean residual, it's the
    // "junk" bin — prefer filling it rather than a roomy bin.
    let res = bin_residual as f64;
    if mean_residual > 0.0 {
        let deviation = (res - mean_residual) / cap;
        score += deviation * 40.0;
    }

    // Open-bin pressure: many open bins -> favor consolidation (reward using bins).
    if open_bins_count > 8 {
        score -= (open_bins_count.min(40) as f64) * 1.5;
    }

    // Tiny tie-breaker on exact residual to keep determinism.
    score += (post_residual % 3) as f64 * 0.01;
    score
}

