    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && (next_item_size <= post_residual) && (post_residual - next_item_size) < 10 {
            score -= 45.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, smoothed by polynomial shaping
    let mut score = norm_pr * (1.0 + 0.8 * norm_pr * (1.0 - norm_pr)) * cap;

    // Non-linear coupling of post_residual with stream progress:
    // early on, tolerate larger residuals (keep bins flexible);
    // late in stream, penalize residual waste more strongly.
    let progress_coupling = 1.0 + 1.5 * progress * progress;
    score *= progress_coupling;

    // Smooth interaction: residual vs mean residual deviation (quadratic)
    let dev = (mean_residual - pr) / cap;
    score += 20.0 * dev * dev;

    // Reward tight fits with smooth saturating term
    let tightness = 1.0 - norm_pr;
    score -= 15.0 * tightness * tightness * (1.0 - norm_pr * norm_pr);

    // Last-chance bin: strong smooth bonus to use it
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: smooth reward if next item fits the post residual
    if next_item_size > 0 {
        let fits_next = if (pr >= next_item_size as f64) { 1.0 } else { 0.0 };
        let slack = ((pr - next_item_size as f64) / cap).max(0.0);
        score -= 12.0 * fits_next * (1.0 - slack);
    } else {
        // last item: minimize residual strongly
        score += 10.0 * norm_pr * norm_pr;
    }

    // Mild penalty for many open bins, smooth in count
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: penalize slightly unless residual would be badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = norm_pr; // equals 1.0 for new bin before coupling
        score += 8.0 - 6.0 * (item_size as f64 / cap);
        let _ = fragmentation;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
