pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: harmonic class of post_residual via integer division thresholds.
    // Classes: 0 (perfect), 1-5 (great), 6-15 (ok), 16-40 (poor), 41+ (very poor).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 15 {
        score -= 15.0;
    } else if post_residual <= 40 {
        score += 10.0;
    } else {
        score += 25.0;
    }

    // Modulo arithmetic on capacity fractions: post_residual divisible classes.
    let pr = post_residual;
    if pr % 25 == 0 && pr > 0 {
        score += 8.0; // exact quarter-capacity gaps are reusable anchors
    }
    if pr % 10 == 0 && pr > 0 && pr < bin_capacity {
        score -= 5.0; // decade-aligned gaps are easy to refill
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 50.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.5;
            // harmonic class of the pair
            if (pr - next_item_size) <= 5 {
                score -= 10.0;
            }
        } else {
            // next item won't fit here; penalize leaving medium dead space
            if pr >= 10 && pr < 40 {
                score += 12.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins have poor fits.
    if bin_residual == bin_capacity {
        // neutral baseline plus pressure from congestion and mean residual
        score = bin_capacity as f64 * 0.9;
        if fitting_bins_count == 0 {
            score -= 80.0; // must open a new bin
        }
        if mean_residual < 20.0 {
            score -= 10.0; // open bins nearly full anyway
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 5.0; // big next item: fresh bin useful
        }
    }

    // Progression: slightly prefer consolidating early, conserving late.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    // Spread pressure: many open bins with high mean residual -> prefer filling existing.
    if open_bins_count > 3 && mean_residual > 30.0 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Any post_residual below the minimum item size (1) is impossible here,
    // but gaps too small to ever be reused by typical items are "dead space".
    // Penalize small-but-nonzero gaps superlinearly: they are the true waste.
    if post_residual > 0 {
        // Small gaps (hard to fill) get a heavy quadratic penalty.
        if post_residual <= 20 {
            score += (21.0 - post_residual as f64) * (21.0 - post_residual as f64) * 1.5;
        } else if post_residual <= 40 {
            // Moderate gaps: mild penalty to prefer tighter fits elsewhere.
            score += (41.0 - post_residual as f64) * 0.5;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // --- Last-chance bonus ---
    // If this is the ONLY bin that can fit the item, using it avoids opening
    // a new bin; reward strongly, scaled by how tight the fit is.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + (bin_residual - item_size) as f64 * 0.3;
    }

    // --- Open-bin pressure ---
    // Favor reusing existing bins when many bins are already open,
    // to keep the active set compact.
    score += open_bins_count as f64 * 0.8;

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin: baseline is post_residual = capacity - item_size,
        // which already looks attractive for small items. Add a fixed opening
        // penalty so we only open when no decent fit exists among open bins.
        score += 55.0;
        // If no open bin fits at all, opening is unavoidable: cancel the penalty.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // --- Lookahead coupling ---
    // If the next item fits exactly into the post_residual, reward this placement
    // (it sets up a perfect follow-up fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 35.0;
        } else if gap <= 15 {
            score -= 10.0;
        }
    }

    // --- Mean-residual alignment ---
    // Slightly prefer bins whose residual is close to the mean (avoid
    // fragmenting one very-full bin while others stay loose).
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    // --- Stream progression ---
    // Late in the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits, but penalize leftover slack after both placements
            let slack2 = (post_residual - next_item_size) as f64;
            score -= 100.0 - slack2 * 0.8;
        } else {
            // next item won't fit here: mild penalty for leaving a trap residual
            score += 30.0;
        }
    }

    // Reward small post_residual relative to mean residual (tight packing)
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a perfect
    // two-item combination (item + next item = capacity)
    if bin_residual == bin_capacity {
        score += 250.0;
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 900.0;
        } else if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 200.0;
        }
    }

    // Prefer tighter fits overall (non-linear waste penalty)
    let waste = post_residual as f64;
    score += 0.02 * waste * waste / bin_capacity as f64;

    // Slight preference for filling larger bins first as stream progresses
    score += (step_index as f64 / total_items.max(1) as f64) * (bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later (below min item size).
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }
    if post_residual == 0 {
        score -= 20.0; // perfect fit bonus
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if next_item_size >= bin_residual && post_residual < next_item_size {
            // bin can't take next item anyway; slight penalty for wasting capacity
            score += 5.0 * (post_residual as f64) / (bin_capacity as f64);
        }
    }

    // Global state: when mean residual is high, prefer filling existing bins
    // rather than proliferating bins.
    score -= 3.0 * (mean_residual / (bin_capacity as f64));

    // New-bin candidate handling: penalize opening a new bin, unless current
    // item is large and fits poorly everywhere.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_penalty = 30.0 + 20.0 * progress;
        // If item is large and mean residual is low, new bin is more acceptable.
        if item_size > 60 && mean_residual < item_size as f64 {
            new_bin_penalty -= 25.0;
        }
        if next_item_size > 0 && next_item_size >= item_size && item_size >= 50 {
            new_bin_penalty -= 10.0; // large pair coming; fresh bin useful
        }
        score += new_bin_penalty;
    }

    // Time horizon: early in stream, be slightly conservative with near-full bins
    // (keep flexible space); late in stream, squeeze everything.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * tightness;

    // Mild penalty for many open bins to discourage bin proliferation.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr;

    // Quadratic/cubic dead-space penalty that intensifies as the stream progresses
    let dead = norm_pr * norm_pr * (1.0 + progress * 2.0) + norm_pr.powi(3) * progress;
    score += 40.0 * dead;

    // Reward tight fits (small post_residual) more strongly later in the stream
    let tight = (1.0 - norm_pr).powi(2);
    score -= 25.0 * tight * (0.3 + progress);

    // Interaction: post_residual vs mean residual — prefer bins near the mean (smoothness)
    let dev = (pr - mean_residual) / cap;
    score += 12.0 * dev * dev * (0.5 + progress);

    // Last-chance bonus: only fitting bin should be strongly favored
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    } else if fitting_bins_count > 1 {
        score -= 5.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if next item fits in post_residual, reward; else penalize smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits = ((pr - nx) / cap).max(0.0);
        let gap = ((nx - pr) / cap).max(0.0);
        score -= 20.0 * (1.0 - fits) * fits * (1.0 + progress);
        score += 15.0 * gap * (0.4 + progress);
    }

    // Mild pressure on many open bins, stronger early when consolidation matters
    score += 3.0 * (open_bins_count as f64).sqrt() * (1.2 - progress);

    // New-bin candidate: penalize opening a new bin smoothly, less so for large items / late stream
    if bin_residual == bin_capacity {
        score += 18.0 * (1.0 - progress) + 10.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: partition residual space into capacity-fraction classes
    let q = (bin_capacity / 4).max(1); // quarter-class quantum
    let post_class = post_residual / q;              // 0..4 harmonic band
    let next_class = (next_item_size / q).min(4);    // harmonic band of lookahead item

    // Reward if next item fits exactly into a harmonic slot of post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        // Perfect modular fit (slack divisible by class quantum) is ideal
        if slack % q == 0 {
            score -= 8.0 + 2.0 * (post_class as f64);
        }
        // Reward closeness of next item to post_residual
        score -= 6.0 * (next_item_size as f64 / post_residual.max(1) as f64);
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize leaving a slot that wastes the band
        score += 4.0 * (post_class as f64);
    }

    // Integer-division thresholds on post_residual: dead-space bands
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny unusable sliver
    } else if post_residual < bin_capacity / 10 {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when current bin fit is poor
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced when item is large relative to capacity
        score = 25.0 - 0.15 * (item_size as f64);
        if next_item_size > 0 && next_item_size > post_residual.max(item_size) {
            score -= 5.0; // lookahead also prefers fresh capacity
        }
        if step_index as f64 / (total_items.max(1) as f64) > 0.5 && open_bins_count > 8 {
            score += 6.0; // late stream with many bins: consolidate instead
        }
    }

    // Mild pressure to prefer tight fits relative to mean residual state
    score += 0.05 * ((post_residual as f64) - mean_residual).max(-20.0).min(20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps too small to hold typical items
    // (sizes >= 10, but unknown distribution -> use graded penalties).
    let pr = post_residual as f64;
    if post_residual == 0 {
        score -= 60.0; // perfect fit: highly desirable
    } else if post_residual < 10 {
        score += 80.0; // unusable micro-gap: heavy penalty
    } else if post_residual < 20 {
        score += 35.0; // nearly unusable dead space
    } else if post_residual < 35 {
        score += 12.0; // awkward gap
    }

    // Reward tight fits relative to item size (waste ratio).
    let waste_ratio = pr / (item_size as f64 + 1.0);
    score += 8.0 * waste_ratio;

    // Last-chance pressure: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins and mean residual.
        score += 25.0 + 6.0 * open_bins_count as f64;
        if mean_residual >= item_size as f64 {
            score += 30.0; // an open bin could already hold this item
        }
        // Early in the stream, opening bins is cheaper (future items may pair).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
    } else {
        // Mild reward for using existing bins as open-bin count grows.
        score -= (open_bins_count as f64).sqrt() * 2.0;
    }

    // Lookahead: if next item fits in the post-residual, reward leaving that space.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    }
    // Penalize blocking the next item: leaving a gap just under next_item_size.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Prefer bins whose residual is close to the item (minimize leftover).
    score += 0.15 * ((bin_residual as f64) - (item_size as f64)).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

