    score += 0.15 * (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chain: next item completes this bin
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how well it uses leftover
            let usage = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * usage;
            // extra bonus for near-exact second-step fit
            let two_step_waste = post_residual as i64 - next_item_size as i64;
            score -= 5.0 * (1.0 - two_step_waste as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize leftover dead space
            let dead = post_residual as f64;
            if dead < next_item_size as f64 {
