            }
        }
    }

    // Relative to mean residual: prefer bins with residual below mean (tighter bins)
    score += 0.08 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when open bins could fit, unless current bin
    // would be left with tiny unusable residue and next item is large
    if bin_residual == bin_capacity {
        // new-bin candidate: neutral baseline with slight penalty so we only
        // open new bins when existing fits are bad
        score += 6.0;
        if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
            score -= 2.0; // fresh bin chains well with next item
        }
        // early stream: allow more bins to keep flexibility
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 4.0 * (1.0 - progress);
    }

    // Slight penalty for very small leftovers that are likely dead space
    if post_residual > 0 && post_residual < 10 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
