    }

    // New-bin candidate calibration: empty bin gets a moderate baseline;
    // only chosen when existing bins score worse (poor fits)
    if bin_residual == bin_capacity {
        score += 80.0;
        // if the item is large relative to capacity, opening fresh bin is attractive
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 40.0;
        }
        // early stream: new bins cheap
        if progress < 0.3 {
            score -= 15.0;
        }
    }

    // Penalize leaving residuals that are awkward (just below common item sizes)
    for r in [10u32, 20, 30, 40, 50].iter() {
        if post_residual > *r && post_residual < *r + 8 {
            score += 12.0;
        }
    }

    // Small coupling: prefer bins whose residual is close to item size (best-fit flavor)
    score += (bin_residual as f64 - item_size as f64).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic polynomial in post_residual, modulated by stream progress.
    // Early: prefer tight fits (low post_residual). Late: tolerate larger residuals
    // less strongly because future opportunity decays.
    let mut score = pr * (1.0 + 0.9 * norm_pr * (1.0 - progress));

    // Smooth cubic interaction: post_residual^3 normalized, penalizing dead space
    // that grows super-linearly as the stream progresses.
    score += 12.0 * norm_pr * norm_pr * norm_pr * (0.5 + progress);

    // Lookahead coupling: reward residuals that can still fit the next item
    // (smooth via ratio), penalize residuals that cannot.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (pr / nxt.max(1.0)).min(1.0);
        score -= 8.0 * fits_next * fits_next * (1.0 - progress);
    } else {
        // Last item: strongly favor minimal post_residual (waste minimization).
        score += 6.0 * norm_pr;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Slight preference for reducing fragmentation relative to mean residual.
    score += 0.05 * (mean_residual - pr).abs();

    // Mild penalty for opening new bins when many are already open.
    score += 0.15 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize dead space into capacity eighths.
    let class = (post_residual * 8 / bin_capacity.max(1)) as i64;
    // Dead space that is too small to be useful (< ~12.5% of capacity) is heavily penalized,
    // except when it is exactly zero (perfect fit).
    if post_residual == 0 {
        score -= 60.0; // perfect fit reward
    } else if post_residual < bin_capacity / 8 {
        score += 45.0; // tiny unusable sliver
    } else if post_residual < bin_capacity / 4 {
        score += 12.0;
    }

    // Lookahead: does the next item fit in the post-residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        // Good: bin stays usable for the next item. Reward proportional to leftover class.
        score -= 20.0 + 0.05 * (post_residual as f64);
    } else if next_item_size > post_residual {
        // Next item won't fit here; penalize more if post-residual is in a "dead" class.
        if class <= 1 && post_residual > 0 {
            score += 15.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Prefer fuller bins: subtract fraction of bin filled.
    score -= (bin_capacity - bin_residual) as f64 / cap * 10.0;

    // New-bin candidate (empty bin): make it mildly attractive only when open bins
    // are mostly full or the item is large relative to typical residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight = mean_residual / cap; // low mean residual => bins nearly full
        let new_bin_score = cap - item_size as f64
            - 25.0 * (1.0 - tight)
            - 20.0 * progress
            - (if fitting_bins_count == 0 { 50.0 } else { 0.0 });
        return new_bin_score;
    }

    // Mild penalty for spreading across many open bins when residuals are large.
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item
    // (or for the lookahead item) are pure waste.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // unusable sliver
        } else if next_item_size > 0 && post_residual < next_item_size {
            score += 35.0; // gap can't hold the next item
        }
    } else {
        score -= 25.0; // perfect closure is ideal
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (bin_residual.max(1) as f64);
    score -= 20.0 * tightness;

    // Last-chance pressure: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: opening a bin should be discouraged unless the current
    // fit is bad and many bins are already open.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // Opening is attractive when the item is large (hard to place later).
        if item_size >= 70 {
            score -= 40.0;
        }
    }

    // Open-bin pressure: mildly discourage spreading across many bins.
    score += 0.5 * open_bins_count as f64;

    // Late in the stream, consolidation matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is close to the item (best-fit flavor).
    score += 0.3 * ((bin_residual as f64 - item_size as f64).abs());

    // If the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 100.0; // perfect two-item completion
        } else if post_residual > next_item_size {
            // next item fits too: penalize leftover after the hypothetical second placement
            let second_leftover = post_residual - next_item_size;
            score -= 30.0 - (second_leftover as f64).min(30.0);
        } else {
            // next item cannot use the residual: penalize dead space scaled by gap
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Compare residual against the mean residual across open bins:
    // prefer bins whose residual is already small (tighter packing).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless it enables
    // a perfect next-item fit or few bins exist.
    if bin_residual == bin_capacity {
        let perfect = next_item_size > 0 && post_residual == next_item_size;
        if perfect {
            score -= 20.0;
        } else if open_bins_count > 0 {
            score += 60.0 + (open_bins_count as f64 * 2.0);
        }
    }

    // Mild progression term: early in the stream, be slightly more willing to open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
