    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight packing (low post residual), non-linearly.
    let x = (pr / cap).clamp(0.0, 1.0);
    let mut score = x * x * (3.0 - 2.0 * x) * cap; // smoothstep on residual fraction

    // Polynomial coupling of post_residual with stream progress:
    // late in the stream, dead space becomes more costly.
