    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Penalize residuals in the "dead zone" that few future items can use
    // (items are >= 1, but small residuals under ~10 are hard to fill exactly).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

