    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the current
    // item is large relative to mean residual space and no tight fit exists.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so new bins are opened only when justified.
        score += 25.0;
        // If item nearly fills a fresh bin (large item), opening is fine.
        if item_size as f64 > 0.7 * cap {
            score -= 20.0;
        }
        // If open bins are fragmented (high mean residual but poor fit),
        // allow opening a new bin.
        if mean_residual > 40.0 && post_residual < item_size as f64 {
            score -= 30.0;
        }
        // Early in the stream, opening bins is cheaper (more future items
        // to fill them); late in the stream, pack tightly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across many bins when mean residual is low
    // (bins are already tight — keep filling them).
    if !is_new_bin && mean_residual < 15.0 {
        score -= 10.0;
    }

    // Non-linear coupling: penalize large post-residuals quadratically
    // scaled by remaining stream length (dead space costs more early).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * post * post / cap * (1.0 - progress);

    score
}

