        let fragmentation = (mean_residual - post_residual as f64).max(0.0);
        score += 30.0 + open_bins_count as f64 * 2.0 - fragmentation * 0.5;
        // Early in the stream, opening bins is cheap; later it is not.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
    } else {
        // Open-bin pressure: mildly prefer fuller bins among many open bins.
        score += open_bins_count as f64 * 0.3;
        // Favor bins with residual below mean (i.e., fuller than average).
        score += (mean_residual - bin_residual as f64) * 0.4;
    }

    // Penalize leaving a gap exactly matching no plausible future item
    // (gap too small for the minimum item size).
    if post_residual > 0 && post_residual < 1 {
        score += 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
