pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // Penalize large dead space that nothing can use later
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score -= 20.0; // small residual still usable-ish
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // prefer tighter bins among many candidates
        score += (post_residual as f64) * 0.5;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 + (post_residual - next_item_size) as f64 * 0.2;
        } else {
            // next item won't fit here: mild penalty for wasting good residual
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // New-bin candidate handling: penalize opening a new bin unless it's
    // genuinely better than any existing fit
    if bin_residual == bin_capacity {
        let mut newbin_score = 70.0;
        // late in the stream, be more conservative about opening bins
        newbin_score += progress * 40.0;
        // if many bins fit the item, opening a new one is wasteful
        if fitting_bins_count > 0 {
            newbin_score += 30.0 * (fitting_bins_count as f64);
        }
        // if mean residual is large, existing bins have room
        newbin_score += mean_residual * 0.3;
        // last-chance existing bin already heavily favored
        if fitting_bins_count == 1 {
            newbin_score += 50.0;
        }
        score += newbin_score;
    }

    // Global state: many open bins -> favor filling existing ones
    score += open_bins_count as f64 * 2.0;

    // Prefer bins whose residual is close to mean (balanced packing)
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
