pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: reward small post-residual with a cubic penalty on normalized waste.
    let mut score = 3.0 * pr / cap + 1.5 * (pr / cap).powi(3);

    // Non-linear coupling: waste hurts more as the stream progresses (less future to absorb it).
    let coupling = (pr / cap) * (0.5 + 2.0 * progress * progress);
    score += coupling * cap / 10.0;

    // Interaction with mean residual: prefer bins whose residual deviates from the mean
    // when the item creates a tight fit (encourages consolidation of similar gaps).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.8 * dev * dev * (pr / cap);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    }

    // Lookahead: penalize leaving a gap that neither fits the next item nor is tiny;
    // reward leaving a gap that exactly accommodates the next item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let fit_quality = (pr - ni) / cap;
            score += 1.2 * fit_quality * fit_quality;
            score -= 1.0 * (pr - ni) / cap;
        } else {
            // Dead space for the next item: penalize proportionally to progress.
            score += 2.5 * (ni - pr) / cap * (0.5 + progress);
        }
    } else {
        // Last item: only tight fits matter.
        score += 2.0 * (pr / cap).powi(2);
    }

    // Mild preference for consolidating into fewer bins early on.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "reusable" classes (multiples of 10, or large enough for typical items)
    // are rewarded; awkward dead-space classes are penalized.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class A: post_residual divisible by 10 -> highly reusable leftover
    if post_residual % 10 == 0 {
        score -= 8.0;
    } else {
        // penalize non-aligned dead space proportionally to how far from a
        // multiple of 10 it lies
        let off = (post_residual % 10) as f64;
        score += 0.4 * off;
    }

    // Class B: integer division thresholds on post_residual
    if post_residual >= 50 {
        score -= 5.0; // half-full leftover still very usable
    } else if post_residual >= 30 {
        score -= 2.0;
    } else if post_residual >= 10 {
        score -= 0.5;
    } else {
        // tiny dead space: waste of capacity
        score += 6.0 * (1.0 - post / 10.0);
    }

    // Lookahead coupling: does post_residual fit the next item exactly /
    // harmonically?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // perfect harmonic match with lookahead
            if post_residual % next_item_size.max(1) == 0 {
                score -= 10.0;
            } else {
                score -= 4.0;
            }
            // reward if the pair (item + next) nearly fills the bin
            let pair_slack = (post_residual - next_item_size) as f64;
            score -= 3.0 * (1.0 - pair_slack / cap).min(1.0);
        } else {
            // next item cannot fit here: mild penalty scaled by overshoot
            let over = (next_item_size - post_residual) as f64;
            score += 0.15 * over;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 7.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer tighter fits, keep base comparison
        score += 0.5 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: an empty bin has post == capacity.
    // Only prefer it when the current item is large or no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 / cap;
        // opening a new bin is attractive for big items late in the stream
        score -= 2.0 + 6.0 * big_item * (0.5 + 0.5 * progress);
        // but discourage hoarding many open bins
        score += 0.35 * open_bins_count as f64;
        if next_item_size > 0 && (next_item_size as f64) / cap > 0.6 {
