        }
    }

    // Mean-residual coupling: if this bin is much emptier than average,
    // it is a better host; if it is the emptiest, slightly deprioritize
    // using it for small items.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= 2.0 * dev;

    // Slight preference to fill bins with high relative fill
    score -= 3.0 * (1.0 - (bin_residual as f64 / cap));

    score
}

