pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near match: next item fits with small slack -> graded reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (-slack / 12.0).exp();
    }

    // Next item does NOT fit in this bin: penalize dead space, worse for tiny post_residual.
    if next_item_size > 0 && next_item_size > post_residual {
        let dead = post_residual as f64;
        score += 25.0 * (1.0 - dead / bin_capacity as f64);
    }

    // Last chance: only this bin can fit the item -> strong reward to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Reward bins that are tighter than the mean residual (good packing candidates).
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Slight penalty for wasting a nearly-full bin on a small item (keep tight bins for small items).
    if item_size < 30 && bin_residual <= item_size + 10 {
        score += 8.0;
    }

    // Late in the stream: consolidate more aggressively into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress;

    // Discourage opening a new bin when several bins already fit the item.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 15.0 + 3.0 * fitting_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: small post_residual is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that cannot fit the average next item.
    if next_item_size > 0 {
        let gap = post_residual as f64;
        if (next_item_size as f64) > gap {
            score += 12.0 * (next_item_size as f64 - gap);
        } else {
            // Reward leaving room for the lookahead item.
            score -= 6.0 * (gap - next_item_size as f64).min(20.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0 + 0.25 * (bin_residual as f64 - item_size as f64);
    } else if fitting_bins_count > 2 {
        // Many options: mildly prefer bins with larger residual (best-fit still dominates).
        score += 0.05 * (fitting_bins_count as f64);
    }

    // Penalize bins far from the mean residual (fragmentation pressure).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // New-bin candidate handling: empty bin gets a mild penalty so it's only chosen
    // when all open bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 + 8.0 * progress;
        // If no open bin fits (fitting_bins_count includes only this new bin), accept it.
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
    }

    // Late in the stream, consolidate: favor reusing existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 0.03 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = r * (1.0 + 0.8 * rn * rn);

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, dead space matters more (harder to reuse)
    let coupling = 1.0 + 1.5 * progress * progress * (1.0 - rn);
    score *= coupling;

    // Penalize very small unusable residuals smoothly (quadratic bowl)
    let small = (rn - 0.05).abs();
    score += 40.0 * small * small * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 25.0 + 30.0 * progress;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 && (next_item_size as f64) <= r {
        score -= 8.0 + 12.0 * progress;
    } else if next_item_size > 0 {
        score += 4.0 * progress;
    }

    // Mild preference for keeping bins balanced vs mean residual
    score += 0.3 * (r - mean_residual).abs();

    // New-bin candidate: make it moderately attractive only when current fit is poor
    if bin_residual == bin_capacity {
        score = 15.0 + 60.0 * rn + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 8 and 12
    let pr = post_residual;
    let residue8 = (pr % 8) as f64;
    let residue12 = (pr % 12) as f64;
    // Penalize post-residuals whose residues are "odd" (poor divisibility => dead space)
    score += residue8 * 0.7 + residue12 * 0.5;

    // Integer division thresholds: post_residual in capacity fractions
    let frac = pr as f64 / cap;
    if frac > 0.5 {
        score -= 12.0; // still roomy, good bin
    } else if frac > 0.25 {
        score += 3.0;
    } else if frac > 0.0 {
        score += 8.0; // near-dead space
    } else {
        score -= 15.0; // perfect fit, exact closure
    }

    // Harmonic class of next item size: does it divide into post_residual?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (next_item_size as u64) <= (pr as u64) {
            // next item fits: reward depending on leftover-after-next residue class
            let after = pr - next_item_size;
            let after_res = (after % 10) as f64;
            score -= 10.0 - after_res * 0.4;
        } else {
            // next item won't fit here; penalize if this bin is the only option
            if fitting_bins_count == 1 {
                score += 20.0;
            } else {
                score += 5.0;
            }
        }
    }

    // Last-chance bonus: strongly prefer using the last fitting bin
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Mean residual coupling: prefer bins tighter than average
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Progress-based new-bin control: early stream, keep bins tight; late stream, consolidate
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // New-bin candidate detection
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive only if average residual is already tight
        // and this item is large (harmonic class of item size)
        let item_frac = item_size as f64 / cap;
        let mut new_bin_score = 55.0;
        if item_frac > 0.6 {
            new_bin_score -= 15.0; // large items deserve fresh space
        }
        if mean_residual < item_size as f64 {
            new_bin_score -= 20.0; // open bins can't help future items
        }
        new_bin_score += progress * 10.0; // late stream: avoid sprawl
        new_bin_score += open_bins_count as f64 * 2.0; // penalize too many open bins
        score = score.min(new_bin_score);
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    let dead_zone: f64 = if post_residual > 0 && post_residual < 10 {
        60.0
    } else if post_residual >= 10 && post_residual < 20 {
        25.0
    } else {
        0.0
    };
    score += dead_zone;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if next item fits into the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item does NOT fit into post residual but would fit a fuller bin usage pattern, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Open bins pressure: prefer filling existing bins when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin, more so mid-stream,
    // unless the current item is large relative to residual elsewhere.
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * (1.0 - progress);
    }

    // Mean residual coupling: if this bin's residual is far below mean, it is a
    // good filler; if far above mean, deprioritize slightly.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.1 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 12 {
        score -= 15.0;
    }

    // Aggressive 2-step lookahead: if the next item can fit exactly into
    // the post-residual, this placement is a chain win.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post == nxt {
            score -= 50.0;
        } else if post >= nxt && post - nxt <= 10.0 {
            score -= 25.0;
        } else if post < nxt && nxt - post <= 10.0 {
            // next item nearly fills the leftover; still decent
            score -= 8.0;
        } else if post < nxt {
            // leftover too small for next item: dead space risk
            score += 10.0;
        }
    }

    // Compare post_residual against mean residual: prefer bins whose
    // remaining space stays close to (but below) the average.
    let diff = post_residual as f64 - mean_residual;
    score += 0.15 * diff;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when good open candidates exist,
    // unless the item is large relative to capacity (hard to place later).
    if bin_residual == bin_capacity {
        let large = item_size as f64 > 0.6 * bin_capacity as f64;
        if !large {
            score += 25.0;
        } else {
            score += 5.0;
        }
    }

    // Late in the stream, avoid waste more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.10 * (post_residual as f64) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for future items (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny unusable slivers
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when item fits poorly everywhere
    // or residual is large and stream is early.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Prefer using open bins early; allow new bins later or when mean residual is tight.
        score += 15.0 * (1.0 - progress) + 0.05 * open_bins_count as f64;
        if mean_residual < item_size as f64 * 0.5 {
            score -= 10.0; // open bins are crowded, new bin is reasonable
        }
    }

    // Lookahead coupling: if the next item would fit exactly in the post-residual,
    // reward this placement; if next item barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 5.0 * (post_residual as f64 - next_item_size as f64) / 10.0;
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            // Next item could have fit with a different choice here
            score += 3.0;
        }
    }

    // Mild preference for filling fuller bins among many open bins (reduce fragmentation).
    score += 0.02 * (bin_residual as f64 - mean_residual).abs().signum()
        * (bin_residual as f64 - mean_residual).abs() * 0.1;

    // Time horizon: as the stream nears its end, avoid opening bins at all costs.
    let remaining = total_items.saturating_sub(step_index);
    if remaining < 5 && is_new_bin {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = it / cap;

    // Core: prefer small post_residual, but with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.5 * progress * pr / cap);

    // Quadratic dead-space penalty: tiny residuals are hard to reuse
    score += 30.0 * (pr / cap).powi(4) * (1.0 + progress);

    // Reward tight fits (post_residual near zero) smoothly via exp-like term
    score -= 20.0 * (-(pr / cap) * 6.0).exp();

    // Penalize bins whose residual deviates from mean (fragmentation balancing)
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead: bonus if post_residual can still fit the next item
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        score -= 8.0 + 4.0 * progress;
    } else if next_item_size > 0 && (next_item_size as f64) > pr {
        // penalize blocking the next item slightly
        score += 3.0 * ((next_item_size as f64 - pr) / cap);
    }

    // New-bin candidate: neutral-ish baseline; make it attractive only when
    // open bins are crowded and item is large
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score = 25.0 + 20.0 * fit_ratio * (1.0 - progress) - 25.0 * crowd * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: how "usable" is the residual?
    // Class 0: residual in {0} perfect; class by divisibility into common item sizes.
    let r = post_residual;
